import json
import logging
import os
import signal
import threading

import pika

log = logging.getLogger("worker")

QUEUE = os.environ.get("JOB_QUEUE", "jobs")
DLX = os.environ.get("JOB_DLX", "jobs.dlx")
DLQ = os.environ.get("JOB_DLQ", "jobs.dead")
MAX_RETRIES = int(os.environ.get("JOB_MAX_RETRIES", "3"))
PREFETCH = int(os.environ.get("JOB_PREFETCH", "10"))


def process_job(payload):
    log.info("processing %s", payload)


def declare_topology(channel):
    channel.exchange_declare(exchange=DLX, exchange_type="fanout", durable=True)
    channel.queue_declare(queue=DLQ, durable=True)
    channel.queue_bind(queue=DLQ, exchange=DLX)
    channel.queue_declare(
        queue=QUEUE, durable=True, arguments={"x-dead-letter-exchange": DLX}
    )


def get_retry_count(properties):
    headers = properties.headers or {}
    return int(headers.get("x-retry-count", 0))


def handle_message(channel, method, properties, body):
    try:
        process_job(json.loads(body))
    except Exception:
        log.exception("job failed")
        retries = get_retry_count(properties)
        if retries < MAX_RETRIES:
            headers = dict(properties.headers or {})
            headers["x-retry-count"] = retries + 1
            channel.basic_publish(
                exchange="",
                routing_key=QUEUE,
                body=body,
                properties=pika.BasicProperties(
                    delivery_mode=2,
                    content_type=properties.content_type,
                    headers=headers,
                ),
            )
            channel.basic_ack(method.delivery_tag)
        else:
            # Retries exhausted: reject without requeue so the DLX routes it to the DLQ.
            channel.basic_nack(method.delivery_tag, requeue=False)
        return
    channel.basic_ack(method.delivery_tag)


def install_signal_handlers(stop_event):
    def handler(signum, frame):
        log.info("signal %s received, shutting down", signum)
        stop_event.set()

    signal.signal(signal.SIGTERM, handler)
    signal.signal(signal.SIGINT, handler)


def run_worker(url):
    stop_event = threading.Event()
    install_signal_handlers(stop_event)
    connection = pika.BlockingConnection(pika.URLParameters(url))
    try:
        channel = connection.channel()
        declare_topology(channel)
        channel.basic_qos(prefetch_count=PREFETCH)
        for method, properties, body in channel.consume(
            QUEUE, inactivity_timeout=1
        ):
            if stop_event.is_set():
                break
            if method is None:
                continue
            handle_message(channel, method, properties, body)
        # Cancels the consumer and requeues any prefetched, unacked messages.
        channel.cancel()
    finally:
        if connection.is_open:
            connection.close()


def main():
    logging.basicConfig(level=logging.INFO)
    run_worker(os.environ.get("AMQP_URL", "amqp://guest:guest@localhost:5672/%2F"))


if __name__ == "__main__":
    main()

